import 'package:test/test.dart';
import 'package:dart_basics_tepenchak/models/university.dart';
void main() { group('Models', () { test('Student GPA and passed courses', () { final s=Student(id:'1',firstName:'A',lastName:'B',birthDate:DateTime(2000)); s.addGrade('DART',80); s.addGrade('MATH',40); expect(s.gpa,60); expect(s.getPassedCourses(),['DART']); expect(Student.fromJson(s.toJson()).fullName,'A B'); }); test('Prerequisites', () { final s=Student(id:'1',firstName:'A',lastName:'B',birthDate:DateTime(2000)); final course=Course(id:'FLUTTER',name:'Flutter',description:'UI',credits:4,instructor:'P',prerequisites:['DART']); expect(course.canStudentEnroll(s),false); s.addGrade('DART',90); expect(course.canStudentEnroll(s),true); }); test('University CRUD', () { final u=University(name:'U'); final s=Student(id:'1',firstName:'A',lastName:'B',birthDate:DateTime(2000)); u.addStudent(s); expect(u.findStudentById('1'),same(s)); u.removeStudent('1'); expect(u.findStudentById('1'),isNull); }); }); }
